import {describe, it, expect, jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry unit', () => {
  it('throws at registration time naming the tool when a static inputSchema cannot be compiled', () => {
    // ([validated by](../../specs/hal-engine-tool-input-validation/spec.md#L18))
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Invalid schema',
          inputSchema: {
            type: 'object',
            properties: {
              age: {type: 'not-a-type'},
            },
          },
        },
        async () => 'result'
      )
    ).toThrow(/broken_tool/);
  });

  it('returns a ToolResponse naming missing required fields and does not call the executor', async () => {
    // ([validated by](../../specs/hal-engine-tool-input-validation/spec.md#L11))
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    registry.register(
      {
        name: 'test_tool',
        description: 'description',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
          required: ['foo'],
        },
      },
      executor
    );

    const response = await registry.execute('test_tool', {});
    const calls = executor.mock.calls;

    expect({
      called: calls.length > 0,
      result: response.result,
    }).toEqual({
      called: false,
      result: expect.stringMatching(/foo.*required/i),
    });
  });

  it('passes valid input with extra properties through unchanged', async () => {
    // ([validated by](../../specs/hal-engine-tool-input-validation/spec.md#L13))
    const registry = new ToolRegistry();
    let capturedInput: any;
    registry.register(
      {
        name: 'test_tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
        },
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    await registry.execute('test_tool', {foo: 'bar', extra: 'qux'});
    expect(capturedInput).toEqual({foo: 'bar', extra: 'qux'});
  });

  it('throws Unknown tool naming the tool for unregistered names', async () => {
    // ([validated by](../../specs/hal-engine-tool-input-validation/spec.md#L14))
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow(/Unknown tool: missing/);
  });

  describe('dynamic tools', () => {
    const setupDynamic = () => {
      const registry = new ToolRegistry();
      const schema = {
        type: 'object',
        properties: {foo: {type: 'string'}},
        required: ['foo'],
      };
      const executor = jest.fn(async () => 'ok');

      return {registry, schema, executor};
    };

    it('caches compiled validators for dynamic schemas by schema object reference', async () => {
      // ([validated by](../../specs/hal-engine-tool-input-validation/spec.md#L20))
      const {registry, schema, executor} = setupDynamic();

      registry.register(
        () => ({
          name: 'dynamic_tool',
          description: 'desc',
          inputSchema: schema,
        }),
        executor
      );

      await registry.execute('dynamic_tool', {foo: 'bar'});
      await registry.execute('dynamic_tool', {foo: 'baz'});

      expect(executor).toHaveBeenCalledTimes(2);
    });

    it('recompiles for dynamic tools when schema object reference changes', async () => {
      // ([validated by](../../specs/hal-engine-tool-input-validation/spec.md#L20))
      const {registry, schema, executor} = setupDynamic();

      registry.register(
        () => ({
          name: 'dynamic_tool',
          description: 'desc',
          inputSchema: schema,
        }),
        executor
      );

      await registry.execute('dynamic_tool', {foo: 'bar'});

      const schema2 = {...schema};
      registry.register(
        () => ({
          name: 'dynamic_tool',
          description: 'desc',
          inputSchema: schema2,
        }),
        executor
      );

      await registry.execute('dynamic_tool', {foo: 'qux'});
      expect(executor).toHaveBeenCalledTimes(2);
    });
  });

  it('compiles a static tool schema once across multiple calls', async () => {
    // ([validated by](../../specs/hal-engine-tool-input-validation/spec.md#L19))
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    registry.register(
      {
        name: 'static_tool',
        description: 'desc',
        inputSchema: {type: 'object', properties: {foo: {type: 'string'}}},
      },
      executor
    );

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {foo: `val${i}`});
    }

    expect(executor).toHaveBeenCalledTimes(10);
  });
});

